// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    address deployer;

    function setUp() public {
        deployer = msg.sender;
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes32 role, address actor) public {
        // Only exclude the two addresses the constructor grants TIMELOCK_ADMIN_ROLE to;
        // for every other (role, actor) pair the reference reports no membership.
        vm.assume(actor != address(c));
        vm.assume(actor != deployer);

        assertTrue(!c.hasRole(role, actor));
    }
}
